<?php
require "db.php";$pageTitle="Enrollment";$id=0;$date=date('Y-m-d');$status="Enrolled";$student="";$course="";
if(isset($_POST['save'])){$id=(int)$_POST['enrollment_id'];$date=mysqli_real_escape_string($conn,$_POST['enrollment_date']);$status=mysqli_real_escape_string($conn,$_POST['status']);$student=(int)$_POST['student_id'];$course=(int)$_POST['course_id'];$sql=$id?"UPDATE enrollment SET enrollment_date='$date',status='$status',student_id=$student,course_id=$course WHERE enrollment_id=$id":"INSERT INTO enrollment(enrollment_date,status,student_id,course_id) VALUES('$date','$status',$student,$course)";if(mysqli_query($conn,$sql)){header("Location: enrollment.php?message=Enrollment saved successfully");exit;}$error=mysqli_error($conn);}
if(isset($_POST['delete'])){$id=(int)$_POST['delete_id'];if(mysqli_query($conn,"DELETE FROM enrollment WHERE enrollment_id=$id")){header("Location: enrollment.php?message=Enrollment deleted successfully");exit;}$error=mysqli_error($conn);}
if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$r=mysqli_fetch_assoc(mysqli_query($conn,"SELECT * FROM enrollment WHERE enrollment_id=$id"));if($r){$date=$r['enrollment_date'];$status=$r['status'];$student=$r['student_id'];$course=$r['course_id'];}}
require "header.php";if(isset($error))echo '<div class="message error">'.htmlspecialchars($error).'</div>';?>
<h1>Enrollment Form</h1><div class="card"><form action="enrollment.php" method="POST"><input type="hidden" name="enrollment_id" value="<?php echo $id;?>"><div class="form-grid"><div class="field"><label>Enrollment Date</label><input type="date" name="enrollment_date" value="<?php echo $date;?>" required></div><div class="field"><label>Status</label><select name="status" required><?php foreach(['Enrolled','Active','Completed','Dropped','Deferred','Cancelled'] as $s)echo '<option '.($status==$s?'selected':'').'>'.$s.'</option>';?></select></div><div class="field"><label>Student</label><select name="student_id" required><option value="">Select Student</option><?php $q=mysqli_query($conn,"SELECT * FROM student ORDER BY reg_no");while($r=mysqli_fetch_assoc($q))echo '<option value="'.$r['student_id'].'" '.($student==$r['student_id']?'selected':'').'>'.htmlspecialchars($r['reg_no'].' - '.$r['first_name'].' '.$r['last_name']).'</option>';?></select></div><div class="field"><label>Course</label><select name="course_id" required><option value="">Select Course</option><?php $q=mysqli_query($conn,"SELECT * FROM course ORDER BY course_code");while($r=mysqli_fetch_assoc($q))echo '<option value="'.$r['course_id'].'" '.($course==$r['course_id']?'selected':'').'>'.htmlspecialchars($r['course_code'].' - '.$r['course_title']).'</option>';?></select></div></div><div class="actions"><button class="btn" name="save"><?php echo $id?'Update Enrollment':'Save Enrollment';?></button><a class="btn secondary" href="enrollment.php">Clear</a></div></form></div>
<div class="card"><h2>Enrollment Records</h2><div class="table-wrap"><table><tr><th>enrollment_id</th><th>Date</th><th>Status</th><th>Student</th><th>Course</th><th>Actions</th></tr><?php $q=mysqli_query($conn,"SELECT e.*,s.reg_no,CONCAT(s.first_name,' ',s.last_name) student_name,c.course_code FROM enrollment e JOIN student s ON s.student_id=e.student_id JOIN course c ON c.course_id=e.course_id ORDER BY e.enrollment_id DESC");while($r=mysqli_fetch_assoc($q)){echo '<tr><td>'.$r['enrollment_id'].'</td><td>'.$r['enrollment_date'].'</td><td>'.$r['status'].'</td><td>'.htmlspecialchars($r['reg_no'].' - '.$r['student_name']).'</td><td>'.htmlspecialchars($r['course_code']).'</td><td><a class="btn" href="enrollment.php?edit='.$r['enrollment_id'].'">Edit</a> <form action="enrollment.php" method="POST" style="display:inline"><input type="hidden" name="delete_id" value="'.$r['enrollment_id'].'"><button class="btn danger" name="delete">Delete</button></form></td></tr>';}?></table></div></div><?php require "footer.php";?>
